"""Generate a rule's starts before overrides (SPEC.md sections 3 and 4)."""

import calendar
import datetime as dt
from dataclasses import dataclass
from math import gcd

from .errors import PlanError
from .instants import LAST_DAY, SECONDS_PER_DAY, format_utc_key, local_day, resolve_local, resolve_shifted
from .rules import ELAPSED_UNITS

MONTHS_PER_GREGORIAN_CYCLE = 400 * 12


@dataclass
class Occurrence:
    __slots__ = ("rule", "key", "start", "end")

    rule: object          # RuleDef
    key: str
    start: int            # UTC timeline seconds
    end: int


def _month_index(day):
    return day.year * 12 + day.month - 1


def _month_dates(rule, first, last):
    anchor = _month_index(rule.start)
    current = _month_index(dt.date.fromordinal(first))
    stop = _month_index(dt.date.fromordinal(last))
    first_month = anchor + (current - anchor + rule.every - 1) // rule.every * rule.every
    # Leap years can change whether an active month has any listed day only for day 29.
    cycle_span = MONTHS_PER_GREGORIAN_CYCLE if 29 in rule.on else 12
    cycle = cycle_span // gcd(rule.every, cycle_span)
    empty_months = 0
    for index in range(first_month, stop + 1, rule.every):
        year, month = divmod(index, 12)
        month += 1
        month_length = calendar.monthrange(year, month)[1]
        days = {month_length if item == "last" else item
                for item in rule.on if item == "last" or item <= month_length}
        if not days:
            # After a complete cycle of empty active months, the pattern repeats.
            empty_months += 1
            if empty_months == cycle:
                return
            continue
        empty_months = 0
        for day in sorted(days):
            value = dt.date(year, month, day)
            if first <= value.toordinal() <= last:
                yield value


def _candidate_dates(rule, first, last):
    anchor = rule.start.toordinal()
    first = max(first, anchor)
    last = min(last, rule.until.toordinal() if rule.until else LAST_DAY)
    if first > last:
        return
    if rule.unit == "month":
        yield from _month_dates(rule, first, last)
        return
    if rule.unit == "week":
        anchor -= rule.start.weekday()
        step = 7 * rule.every
        weekdays = rule.on
    else:
        step = rule.every
        weekdays = (0,)
    first_period = anchor + (first - anchor) // step * step
    for period in range(first_period, last + 1, step):
        for weekday in weekdays:
            ordinal = period + weekday
            if first <= ordinal <= last:
                yield dt.date.fromordinal(ordinal)


def _regular_calendar_starts(ruledef, first, last):
    for day in _candidate_dates(ruledef.rule, first, last):
        seen = set()
        for time in ruledef.rule.at:
            local = dt.datetime.combine(day, time)
            start = resolve_local(local, ruledef.tz)
            if start not in seen:
                seen.add(start)
                yield local, start


def _shifted_calendar_starts(ruledef, first, last, target_day):
    # Only nominal times surviving step 2 can hold a slot on the target date.
    blocked = {local.time() for local, _ in _regular_calendar_starts(ruledef, target_day, target_day)}
    available = set(ruledef.rule.at) - blocked
    if not available:
        return
    for local, _ in _regular_calendar_starts(ruledef, first, last):
        time = local.time()
        if time in available:
            yield local, resolve_shifted(target_day, time, ruledef.tz)
            available.remove(time)
            if not available:
                return


def _calendar_starts_after_holidays(ruledef, first, last):
    holidays = ruledef.holidays
    if ruledef.holiday == "keep" or not holidays:
        yield from _regular_calendar_starts(ruledef, first, last)
        return

    cursor = first
    for start, end in holidays.overlapping(first, last):
        yield from _regular_calendar_starts(ruledef, cursor, start - 1)
        if ruledef.holiday == "shift":
            yield from _shifted_calendar_starts(ruledef, max(cursor, start), min(last, end), end + 1)
        cursor = end + 1
    yield from _regular_calendar_starts(ruledef, cursor, last)


def calendar_starts(ruledef, first, last):
    """Yield (key, instant) pairs for the inclusive range of original date ordinals."""
    rule = ruledef.rule
    search = rule.start.toordinal() if rule.times is not None else first
    if ruledef.holiday == "shift":
        block = ruledef.holidays.containing(search)
        if block:
            search = block[0]
    search = max(search, rule.start.toordinal())
    last = min(last, rule.until.toordinal() if rule.until else LAST_DAY)
    if search > last:
        return
    for index, (local, start) in enumerate(_calendar_starts_after_holidays(ruledef, search, last), 1):
        if local.toordinal() >= first:
            yield local.isoformat(timespec="minutes"), start
        if index == rule.times:
            return


def _aligned(anchor, step, earliest):
    return anchor + max(0, (earliest - anchor + step - 1) // step) * step


def _elapsed_starts_after_holidays(ruledef, first, last):
    rule = ruledef.rule
    anchor = resolve_local(dt.datetime.combine(rule.start, rule.anchor_time), ruledef.tz)
    step = rule.every * ELAPSED_UNITS[rule.unit]
    holidays = ruledef.holidays if ruledef.holiday == "skip" else None
    until = rule.until.toordinal() if rule.until else None
    if not holidays and until is None:
        if rule.times is not None:
            last = min(last, anchor + (rule.times - 1) * step)
        yield from range(_aligned(anchor, step, first), last + 1, step)
        return

    if rule.times is not None:
        first = anchor
    if until is not None:
        # A UTC offset has magnitude less than a day.
        last = min(last, (until + 1) * SECONDS_PER_DAY - 1)
    at = _aligned(anchor, step, first)
    while at <= last:
        day = local_day(at, ruledef.tz)
        if until is None or day <= until:
            block = holidays.containing(day) if holidays else None
            if not block:
                yield at
            elif at + step >= block[0] * SECONDS_PER_DAY:
                # Jump over the interior of the holiday. Check the edges in case
                # an offset change near midnight returns to an earlier local date.
                safe_end = (block[1] - 1) * SECONDS_PER_DAY
                at = _aligned(anchor, step, max(at + step, safe_end))
                continue
        at += step


def elapsed_starts(ruledef, first, last):
    """Yield (UTC key, instant) pairs for the inclusive range of UTC seconds."""
    for index, at in enumerate(_elapsed_starts_after_holidays(ruledef, first, last), 1):
        if at >= first:
            try:
                key = format_utc_key(at)
            except OverflowError:
                raise PlanError(f"rule {ruledef.id}: UTC key outside the supported calendar") from None
            yield key, at
        if index == ruledef.rule.times:
            return
"""Validate holiday entries and index their merged inclusive date ranges."""

from bisect import bisect_left, bisect_right

from .errors import PlanError
from .rules import parse_date


class Holidays:
    def __init__(self, entries):
        if not isinstance(entries, list):
            raise PlanError("holidays must be a list")

        ranges = []
        for entry in entries:
            if not isinstance(entry, str):
                raise PlanError("holiday entries must be strings")
            first, separator, last = entry.partition("..")
            try:
                start = parse_date(first).toordinal()
                end = parse_date(last).toordinal() if separator else start
            except ValueError:
                raise PlanError(f"invalid holiday {entry!r}") from None
            if end < start:
                raise PlanError(f"holiday range ends before it starts: {entry!r}")
            ranges.append((start, end))

        self._starts = []
        self._ends = []
        for start, end in sorted(ranges):
            if self._ends and start <= self._ends[-1] + 1:
                self._ends[-1] = max(self._ends[-1], end)
            else:
                self._starts.append(start)
                self._ends.append(end)

    def __bool__(self):
        return bool(self._starts)

    def containing(self, day):
        index = bisect_right(self._starts, day) - 1
        if index >= 0 and day <= self._ends[index]:
            return self._starts[index], self._ends[index]

    def overlapping(self, first, last):
        start = bisect_left(self._ends, first)
        end = bisect_right(self._starts, last)
        for index in range(start, end):
            yield self._starts[index], self._ends[index]
"""Queries over a plan (SPEC.md sections 6 and 7)."""

import heapq

from .errors import PlanError
from .expand import Occurrence, calendar_starts, elapsed_starts
from .instants import SECONDS_PER_DAY, format_instant, parse_bound
from .plan import load_plan


def _collect(plan, start, end):
    for ruledef in plan.rules:
        length = ruledef.rule.minutes * 60
        if ruledef.rule.elapsed:
            starts = elapsed_starts(ruledef, start - length + 1, end - 1)
        else:
            # The target wall time differs from UTC by less than a day, even in a gap.
            first = (start - length - SECONDS_PER_DAY) // SECONDS_PER_DAY + 1
            last = (end + SECONDS_PER_DAY - 1) // SECONDS_PER_DAY + 1
            if ruledef.holiday == "shift":
                block = ruledef.holidays.containing(first - 1)
                if block:
                    first = block[0]
            starts = calendar_starts(ruledef, first, last)
        for key, at in starts:
            if key not in ruledef.overrides and at < end and at + length > start:
                yield Occurrence(ruledef, key, at, at + length)

        # A move can overlap the window even when its original key is far outside it.
        for key, override in ruledef.overrides.items():
            if override.action == "move":
                at = override.start
                finish = at + override.minutes * 60
                if at < end and finish > start:
                    yield Occurrence(ruledef, key, at, finish)


def _as_dict(occ, start, end):
    try:
        return {
            "rule": occ.rule.id,
            "key": occ.key,
            "start": format_instant(start, occ.rule.tz),
            "end": format_instant(end, occ.rule.tz),
        }
    except OverflowError:
        raise PlanError(f"rule {occ.rule.id}: timestamp outside the supported calendar") from None


def _window(start, end):
    lo, hi = parse_bound(start), parse_bound(end)
    if hi <= lo:
        raise PlanError("end must be after start")
    return lo, hi


def occurrences(plan, start, end):
    plan = load_plan(plan)
    lo, hi = _window(start, end)
    ordered = sorted(_collect(plan, lo, hi),
                     key=lambda occ: (occ.start, occ.end, -occ.rule.priority, occ.rule.index, occ.key))
    return [_as_dict(occ, occ.start, occ.end) for occ in ordered]


def _segments(occurrences):
    """Sweep whole intervals and yield maximal spans with the same winner."""
    events = {}
    for occ in occurrences:
        events.setdefault(occ.start, []).append(occ)
        events.setdefault(occ.end, [])

    active = []
    winner = segment_start = None
    for at in sorted(events):
        for occ in events[at]:
            rank = (-occ.rule.priority, occ.start, occ.rule.index, occ.key)
            heapq.heappush(active, (rank, occ))
        while active and active[0][1].end <= at:
            heapq.heappop(active)

        next_winner = active[0][1] if active else None
        if next_winner is not winner:
            if winner is not None:
                yield winner, segment_start, at
            winner, segment_start = next_winner, at


def agenda(plan, start, end):
    plan = load_plan(plan)
    lo, hi = _window(start, end)
    minimum = plan.min_segment * 60
    results = []
    for occ, start, end in _segments(_collect(plan, lo, hi)):
        if (start != occ.start or end != occ.end) and end - start < minimum:
            continue
        start, end = max(start, lo), min(end, hi)
        if start < end:
            results.append(_as_dict(occ, start, end))
    return results
@dataclass
class Plan:
    rules: list
    min_segment: int


@lru_cache(maxsize=1)
def _zone_names(_tzpath):
    # Key the cache by TZPATH so a reset to a different database is picked up.
    return zoneinfo.available_timezones()


def _zone(name, context):
    if not isinstance(name, str):
        raise PlanError(f"{context}timezone must be an IANA zone name")
    # ZoneInfo can open miscapitalized names on case-insensitive filesystems.
    if name == "localtime" or name not in _zone_names(zoneinfo.TZPATH):
        raise PlanError(f"{context}unknown timezone {name!r}")
    try:
        return zoneinfo.ZoneInfo(name)
    except (OSError, ValueError, zoneinfo.ZoneInfoNotFoundError):
        raise PlanError(f"{context}unknown timezone {name!r}") from None


def _load_rule(item, index, default_tz, holidays, by_id):
    if not isinstance(item, dict):
        raise PlanError(f"rule #{index} must be an object")
    rid = item.get("id")
    if not isinstance(rid, str):
        raise PlanError(f"rule #{index}: id must be a string")
    if not re.fullmatch(r"[A-Za-z0-9_-]+", rid):
        raise PlanError(f"rule #{index} has invalid id {rid!r}")
    if rid in by_id:
        raise PlanError(f"rule {rid}: duplicate id")
    text = item.get("rule")
    if not isinstance(text, str):
        raise PlanError(f"rule {rid}: rule text must be a string")
    try:
        rule = parse_rule(text)
    except RuleSyntaxError as exc:
        raise RuleSyntaxError(f"rule {rid}: {exc}", exc.position, text) from None
    tz = _zone(item["timezone"], f"rule {rid}: ") if "timezone" in item else default_tz
    priority = item.get("priority", 0)
    if type(priority) is not int:
        raise PlanError(f"rule {rid}: priority must be an integer")
    holiday = item.get("holiday", "keep")
    if holiday not in ("keep", "skip", "shift"):
        raise PlanError(f"rule {rid}: holiday must be 'keep', 'skip', or 'shift'")
    if rule.elapsed and holiday == "shift":
        raise PlanError(f"rule {rid}: minute and hour rules cannot shift holidays")
    return RuleDef(index, rid, rule, tz, priority, holiday, holidays)


def _load_override(item, by_id):
    if not isinstance(item, dict):
        raise PlanError("override must be an object")
    rid = item.get("rule")
    if not isinstance(rid, str):
        raise PlanError("override rule id must be a string")
    if rid not in by_id:
        raise PlanError(f"override for unknown rule {rid!r}")
    ruledef = by_id[rid]
    key = item.get("key")
    if not isinstance(key, str):
        raise PlanError(f"rule {rid}: override key must be a string")
    if len(key) == 10 and len(ruledef.rule.at) == 1:
        key += "T" + ruledef.rule.at[0].isoformat(timespec="minutes")
    try:
        if ruledef.rule.elapsed:
            parse_utc_key(key)
        else:
            parse_local(key)
    except ValueError:
        raise PlanError(f"rule {rid}: invalid override key {key!r}") from None
    if key in ruledef.overrides:
        raise PlanError(f"rule {rid}: duplicate override for {key}")

    action = item.get("action")
    if not isinstance(action, str):
        raise PlanError(f"rule {rid}: override action must be a string")
    if action == "cancel":
        ruledef.overrides[key] = Override(action)
    elif action == "move":
        try:
            to = parse_local(item.get("to"))
        except ValueError:
            raise PlanError(f"rule {rid}: move override needs a valid 'to'") from None
        minutes = ruledef.rule.minutes
        if "for" in item:
            minutes = parse_duration(item["for"])
            if minutes is None:
                raise PlanError(f"rule {rid}: invalid override duration")
        ruledef.overrides[key] = Override(action, resolve_local(to, ruledef.tz), minutes)
    else:
        raise PlanError(f"rule {rid}: unknown override action {action!r}")


def _validate_override_keys(ruledef):
    if not ruledef.overrides:
        return

    pending = set(ruledef.overrides)
    if ruledef.rule.elapsed:
        # Historical offsets can place the start partway through its key's UTC minute.
        positions = {parse_utc_key(key) for key in pending}
        candidates, extra = elapsed_starts, 59
    else:
        positions = {parse_local(key).toordinal() for key in pending}
        candidates, extra = calendar_starts, 0
    if ruledef.rule.times is None:
        ranges = [(position, position + extra) for position in positions]
    else:
        ranges = [(min(positions), max(positions) + extra)]
    for first, last in ranges:
        for key, _ in candidates(ruledef, first, last):
            pending.discard(key)
            if not pending:
                return
    key = min(pending)
    raise PlanError(f"rule {ruledef.id}: override key {key} does not name an occurrence")


def load_plan(raw):
    if not isinstance(raw, dict):
        raise PlanError("plan must be an object")
    if "timezone" not in raw:
        raise PlanError("plan has no timezone")
    default_tz = _zone(raw["timezone"], "")
    items = raw.get("rules")
    if not isinstance(items, list):
        raise PlanError("rules must be a list")
    holidays = Holidays(raw.get("holidays", []))
    by_id = {}
    for index, item in enumerate(items):
        ruledef = _load_rule(item, index, default_tz, holidays, by_id)
        by_id[ruledef.id] = ruledef

    overrides = raw.get("overrides", [])
    if not isinstance(overrides, list):
        raise PlanError("overrides must be a list")
    for item in overrides:
        _load_override(item, by_id)

import json
import sys

from .errors import PlanError, RuleSyntaxError
from .query import agenda, occurrences
from .rules import canonical, parse_integer


def _reject_constant(value):
    raise ValueError(f"invalid JSON constant {value}")


def _print_error(exc):
    print(f"error: {exc}", file=sys.stderr)
    if isinstance(exc, RuleSyntaxError):
        print(exc.text, file=sys.stderr)
        print(" " * exc.position + "^", file=sys.stderr)


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if len(argv) == 2 and argv[0] == "canonical":
        try:
            print(canonical(argv[1]))
        except PlanError as exc:
            _print_error(exc)
            return 2
        return 0
    if len(argv) != 4 or argv[0] not in ("occurrences", "agenda"):
        print("usage: python3 -m cadence {occurrences,agenda} START END PLAN.json", file=sys.stderr)
        print("       python3 -m cadence canonical RULE", file=sys.stderr)
        return 1
    command, start, end, path = argv
    try:
        with open(path, "rb") as f:
            plan = json.load(f, parse_int=parse_integer, parse_constant=_reject_constant)
    except (OSError, ValueError, RecursionError) as exc:
        _print_error(exc)
        return 1
    try:
        query = occurrences if command == "occurrences" else agenda
        rows = query(plan, start, end)
    except PlanError as exc:
        _print_error(exc)
        return 2
    if not rows:
        print("nothing scheduled")
    for row in rows:
        print(row["start"], row["end"], row["rule"], row["key"])
    return 0
"""Convert between wall-clock date-times and whole seconds on the UTC timeline."""

import datetime as dt
import re
from functools import lru_cache

from .errors import PlanError
from .rules import LOCAL_DATETIME, parse_local

SECONDS_PER_DAY = 24 * 60 * 60
EPOCH = dt.datetime.min
UTC_EPOCH = EPOCH.replace(tzinfo=dt.timezone.utc)
LAST_DAY = dt.date.max.toordinal()
BOUND = re.compile(rf"{LOCAL_DATETIME}(?::[0-9]{{2}})?(?:Z|[+-](?:[01][0-9]|2[0-3]):[0-5][0-9])")


def parse_utc_key(key):
    if not key.endswith("Z"):
        raise ValueError("expected a UTC key")
    utc = parse_local(key[:-1]).replace(tzinfo=dt.timezone.utc)
    return to_instant(utc)


@lru_cache(maxsize=4096)
def format_utc_key(instant):
    return (EPOCH + dt.timedelta(seconds=instant)).isoformat(timespec="minutes") + "Z"


def to_instant(local):
    offset = local.utcoffset()
    return int((local.replace(tzinfo=None) - EPOCH - offset).total_seconds())


def resolve_local(local, zone):
    # fold=0 uses the pre-transition offset for both repeated and missing times.
    # For a gap this is equivalent to moving the wall time forward by the gap.
    return to_instant(local.replace(tzinfo=zone, fold=0))


def resolve_shifted(day, time, zone):
    if day <= LAST_DAY:
        return resolve_local(dt.datetime.combine(dt.date.fromordinal(day), time), zone)
    # Keep the original key usable by overrides even if a final holiday range
    # shifts its start beyond the dates that the timestamp format can represent.
    offset = int(zone.utcoffset(dt.datetime.max).total_seconds())
    return (day - 1) * SECONDS_PER_DAY + time.hour * 3600 + time.minute * 60 - offset


def parse_bound(text):
    if not isinstance(text, str):
        raise PlanError("date-time must be a string")
    if BOUND.fullmatch(text):
        try:
            return to_instant(dt.datetime.fromisoformat(text.replace("Z", "+00:00")))
        except ValueError:
            pass
    raise PlanError(f"invalid date-time {text!r}")


def local_datetime(instant, zone):
    day = instant // SECONDS_PER_DAY + 1
    if 1 <= day <= LAST_DAY:
        utc = UTC_EPOCH + dt.timedelta(seconds=instant)
        return utc.astimezone(zone)
    # A date at a calendar boundary can still be in range in the rule's zone.
    boundary = dt.datetime.min if day < 1 else dt.datetime.max
    offset = zone.utcoffset(boundary)
    return (EPOCH + (dt.timedelta(seconds=instant) + offset)).replace(tzinfo=zone)


@lru_cache(maxsize=8192)
def local_day(instant, zone):
    try:
        return local_datetime(instant, zone).toordinal()
    except OverflowError:
        # The UTC instant can be in range while the local date is outside it.
        return 0 if instant < SECONDS_PER_DAY else LAST_DAY + 1


@lru_cache(maxsize=4096)
def format_instant(instant, zone):
    # Keep the local wall time and use the output format's minute-precision offset.
    stamp = local_datetime(instant, zone).isoformat(timespec="seconds")
    offset = stamp[19:25]
    return stamp[:19] + ("+00:00" if offset == "-00:00" else offset)
"""Rule text parsing (SPEC.md section 2)."""

import datetime as dt
import re
from dataclasses import dataclass, field

from .errors import RuleSyntaxError

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
UNITS = {"day": "day", "days": "day", "week": "week", "weeks": "week",
         "month": "month", "months": "month", "minute": "minute", "minutes": "minute",
         "hour": "hour", "hours": "hour"}
ELAPSED_UNITS = {"minute": 60, "hour": 3600}
DATE = r"[0-9]{4}-[0-9]{2}-[0-9]{2}"
TIME = r"[0-9]{2}:[0-9]{2}"
LOCAL_DATETIME = rf"{DATE}T{TIME}"
POSITIVE_INTEGER = r"[1-9][0-9]*"
DURATION = re.compile(
    rf"(?:({POSITIVE_INTEGER})d)?(?:({POSITIVE_INTEGER})h)?(?:({POSITIVE_INTEGER})m)?"
)


@dataclass
class Rule:
    every: int = 1
    unit: str = "day"
    on: list = field(default_factory=list)   # weekday indexes, or month days / "last"
    at: list = field(default_factory=list)   # datetime.time
    minutes: int = 0
    start: dt.date = None
    anchor_time: dt.time = None
    until: dt.date = None
    times: int = None

    @property
    def elapsed(self):
        return self.unit in ELAPSED_UNITS


def parse_integer(text):
    try:
        return int(text)
    except ValueError:
        # Python caps the size of a single decimal conversion. The grammar does not.
        digits = text.removeprefix("-")
        value = 0
        for start in range(0, len(digits), 500):
            part = digits[start:start + 500]
            value = value * 10 ** len(part) + int(part)
        return -value if text.startswith("-") else value


def _format_integer(number):
    try:
        return str(number)
    except ValueError:
        parts = []
        while number >= 10 ** 500:
            number, part = divmod(number, 10 ** 500)
            parts.append(f"{part:0500d}")
        return str(number) + "".join(reversed(parts))


def parse_duration(word):
    """Return the duration in minutes, or None for an invalid token."""
    match = DURATION.fullmatch(word.lower()) if isinstance(word, str) and word else None
    if match is None:
        return None
    return sum(parse_integer(part) * scale
               for part, scale in zip(match.groups(), (1440, 60, 1)) if part)


def format_duration(minutes):
    days, minutes = divmod(minutes, 1440)
    hours, minutes = divmod(minutes, 60)
    return "".join(_format_integer(n) + unit
                   for n, unit in ((days, "d"), (hours, "h"), (minutes, "m")) if n)


def _count(word):
    if re.fullmatch(POSITIVE_INTEGER, word):
        return parse_integer(word)


def parse_date(word):
    if not re.fullmatch(DATE, word):
        raise ValueError("expected a date")
    return dt.date.fromisoformat(word)


def parse_local(word):
    if not isinstance(word, str) or not re.fullmatch(LOCAL_DATETIME, word):
        raise ValueError("expected a local date-time")
    return dt.datetime.fromisoformat(word)


def _time(word):
    if re.fullmatch(TIME, word):
        return dt.time.fromisoformat(word)


def _month_day(word):
    if word == "last":
        return word
    if re.fullmatch(r"[1-9]|[12][0-9]|3[01]", word):
        return int(word)


def _parse_list(word, parse_item, order=None):
    items = [parse_item(part) for part in word.split(",")]
    if None not in items and len(items) == len(set(items)):
        return sorted(items, key=order)


class _Words:
    def __init__(self, text):
        self.text = text
        self.tokens = list(re.finditer(r"[^ \t]+", text))
        self.index = 0

    def peek(self):
        if self.index < len(self.tokens):
            return self.tokens[self.index].group().lower()

    def error(self, message):
        position = self.tokens[self.index].start() if self.index < len(self.tokens) else len(self.text)
        return RuleSyntaxError(message, position, self.text)

    def expect(self, keyword):
        if self.peek() != keyword:
            raise self.error(f"expected '{keyword}'")
        self.index += 1

    def convert(self, what, convert):
        word = self.peek()
        if word is None:
            raise self.error(f"expected {what}, found end of rule")
        try:
            value = convert(word)
        except (ValueError, KeyError):
            value = None
        if value is None:
            raise self.error(f"expected {what}, found {self.tokens[self.index].group()!r}")
        self.index += 1
        return value


def parse_rule(text):
    if not isinstance(text, str):
        raise RuleSyntaxError("rule text must be a string", 0)
    w = _Words(text)
    w.expect("every")
    rule = Rule()
    word = w.peek()
    if word and word[0] in "0123456789":
        rule.every = w.convert("a count", _count)
    rule.unit = w.convert("a unit", UNITS.__getitem__)
    if rule.unit in ("week", "month") and w.peek() == "on":
        w.expect("on")
        if rule.unit == "week":
            rule.on = w.convert("weekdays", lambda s: _parse_list(s, WEEKDAYS.index))
        else:
            rule.on = w.convert("month days", lambda s: _parse_list(
                s, _month_day, lambda day: 32 if day == "last" else day))
    if not rule.elapsed:
        w.expect("at")
        rule.at = w.convert("times", lambda s: _parse_list(s, _time))
    w.expect("for")
    rule.minutes = w.convert("a duration", parse_duration)
    w.expect("from")
    if rule.elapsed:
        anchor = w.convert("a local date-time", lambda word: parse_local(word.upper()))
        rule.start, rule.anchor_time = anchor.date(), anchor.time()
    else:
        rule.start = w.convert("a date", parse_date)
    if w.peek() == "until":
        w.expect("until")

        def end_date(word):
            value = parse_date(word)
            if value >= rule.start:
                return value

        rule.until = w.convert("an until date on or after the from date", end_date)
    elif w.peek() == "times":
        w.expect("times")
        rule.times = w.convert("a count", _count)
    if w.peek() is not None:
        raise w.error("unexpected token after rule")
    if not rule.on:
        if rule.unit == "week":
            rule.on = [rule.start.weekday()]
        elif rule.unit == "month":
            rule.on = [rule.start.day]
    return rule


def canonical(text):
    rule = parse_rule(text)
    unit = rule.unit if rule.every == 1 else rule.unit + "s"
    out = ["every", _format_integer(rule.every), unit]
    if rule.unit == "week":
        out += ["on", ",".join(WEEKDAYS[d] for d in rule.on)]
    elif rule.unit == "month":
        out += ["on", ",".join(str(d) for d in rule.on)]
    if not rule.elapsed:
        out += ["at", ",".join(t.isoformat(timespec="minutes") for t in rule.at)]
    out += ["for", format_duration(rule.minutes)]
    start = rule.start.isoformat()
    if rule.elapsed:
        start += "T" + rule.anchor_time.isoformat(timespec="minutes")
    out += ["from", start]
    if rule.until is not None:
        out += ["until", rule.until.isoformat()]
    if rule.times is not None:
        out += ["times", _format_integer(rule.times)]
    return " ".join(out)
## 6. `occurrences(plan, start, end)`

- `start` and `end` are strings: `YYYY-MM-DDTHH:MM`, optionally `:SS`, then `Z` or an offset `±HH:MM`. They bound a half-open window `[start, end)`. Anything else, or an `end` that is not after `start`, is an error.
- The result is every occurrence, from every rule, that overlaps the window: `occurrence.start < end and occurrence.end > start`, compared as instants, using final times (after step 4). Occurrences are returned whole, not cut to the window.
- Each is a dict `{"rule": id, "key": key, "start": timestamp, "end": timestamp}`.
- Order: by start instant; then by end instant; then higher `priority` first; then the rule that comes first in the plan.

## 7. `agenda(plan, start, end)`

`agenda` takes exactly the occurrences `occurrences(plan, start, end)` returns and removes overlaps, so that no instant belongs to two of them.

- Occurrence X **outranks** Y if X has the higher priority; with equal priorities, the earlier start; with equal starts, the rule that comes first in the plan; within one rule, the smaller key.
- Each occurrence keeps those parts of its interval that are not covered by the **whole** interval of any occurrence that outranks it. Every maximal part it keeps is a **segment**.
- `min_segment`: if an occurrence lost any time this way, its segments shorter than `min_segment` are discarded. An occurrence that lost nothing is never discarded, however short. Discarded time is not given to anyone else.
- Then segments are cut to the window (`min_segment` looks at lengths before this cut); segments with nothing inside the window disappear.
- The result is the list of segments ordered by start. A segment is a dict like in section 6, with the segment's own `start` and `end`.

## 8. Errors

- Invalid rule text → `cadence.RuleSyntaxError` (section 2). When the text belongs to a rule in a plan, the message contains the rule's id and `position` is still an index into that rule's text.
- Everything else that is invalid (plan, override, query argument) → `cadence.PlanError`. When the problem is in a rule or in an override of a rule, the message contains that rule's id.
- `RuleSyntaxError` is a subclass of `PlanError`.

## 9. Python API

```python
import cadence

cadence.canonical(text: str) -> str
cadence.occurrences(plan: dict, start: str, end: str) -> list[dict]
cadence.agenda(plan: dict, start: str, end: str) -> list[dict]
cadence.PlanError
cadence.RuleSyntaxError        # .position
```

## 10. CLI

```
python3 -m cadence occurrences START END PLAN.json
python3 -m cadence agenda START END PLAN.json
python3 -m cadence canonical "RULE TEXT"
```

- `occurrences` and `agenda` print one line per result, in order: `START END RULE KEY` separated by single spaces, e.g. `2025-03-05T09:30:00+01:00 2025-03-05T09:45:00+01:00 standup 2025-03-05T09:30`. With no results they print `nothing scheduled`.
- `canonical` prints the canonical form.
- `PlanError`: print `error: <message>` to stderr, exit with status 2. For a `RuleSyntaxError`, two more lines follow on stderr: the offending rule text exactly as given, then a line of `position` spaces followed by `^`.
- A plan file that can't be read or isn't valid JSON: print `error: <message>` to stderr, exit with status 1.
- Otherwise exit with status 0.

## 11. Performance

For every rule unit, the cost of a query must not grow with the distance between a rule's `from` date or date-time and the window. A plan with 200 rules that start in 1970, queried for one day in 2060, must answer in well under a second. A rule with `times N` may take time proportional to `N`.
